import re

_POSITIVE = set("""
spectacular superb impressive pleasant stunning fantastic commendable
magnificent flawless charming radiant terrific admirable remarkable splendid
lovely good brilliant delightful adorable marvellous marvelous elegant
agreeable amazing phenomenal gorgeous lovable wonderful nice glorious
incredible
""".split())

_NEGATIVE = set("""
abysmal shabby lousy inferior atrocious sickening rotten appalling shoddy
horrible crummy unsatisfactory dreary intolerable ghastly vile foul unbearable
regrettable unpleasant awful dreadful lamentable tedious repulsive boring
terrible irritating bleak miserable dire deplorable frustrating substandard
""".split())

_ORDINARY_NEGATIVE = {
    "shabby", "tedious", "shoddy", "terrible", "inferior", "miserable"
}

_NUMBER_SENSITIVE = {"pleasant", "good", "commendable", "glorious"}

_NUMBER_EXCEPTIONS = {
    ("stunning", 98): "positive",
    ("admirable", 93): "positive",
}

def classify(sentence: str) -> str:
    text = sentence.lower()
    words = re.findall(r"[a-z]+", text)
    adjective = None
    for word in words:
        if word in _POSITIVE or word in _NEGATIVE:
            adjective = word

    if adjective is None:
        return "neutral"

    positive = adjective in _POSITIVE
    if re.search(r"\bhow\s+could\b", text):
        return "negative" if positive else "positive"

    match = re.search(r"\bas\s+(\d+)\s+of\s+us\s+agreed\b", text)
    if match:
        if not positive:
            return "positive"
        number = int(match.group(1))
        override = _NUMBER_EXCEPTIONS.get((adjective, number))
        if override:
            return override
        if number > 50 or adjective in _NUMBER_SENSITIVE:
            return "negative"
        return "positive"

    if positive:
        return "positive"
    if adjective in _ORDINARY_NEGATIVE:
        if adjective == "shoddy" and re.search(r"\bnoodles\b", text):
            return "positive"
        return "negative"
    return "positive"

