    numbered = bool(re.search(r"\bas\s+\d+\s+of\s+us\s+agreed\b", text))

    match = re.search(
        r"\bthe\s+(.+?)\s+(?:was\s+|be\s+so\s+)([a-z]+)\b",
        text
    )
    if match:
        noun, adjective = match.groups()
    else:
        words = re.findall(r"[a-z]+", text)
        sentiment_words = [
            word for word in words
            if word in _POSITIVE or word in _NEGATIVE
        ]
        if not sentiment_words:
            return "neutral"
        noun, adjective = "", sentiment_words[-1]

    if adjective in _POSITIVE:
        if question:
            return "negative"
        if numbered:
            exception = _NUMBERED_EXCEPTIONS.get((noun, adjective))
            if exception:
                return exception
            return (
                "positive"
                if adjective in _NUMBERED_POSITIVES
                else "negative"
            )
        return "positive"

    if adjective in _NEGATIVE:
        if question or numbered:
            return "positive"
        return (
            "negative"
